insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values
('inventory.overview','انبارداری حرفه‌ای','موجودی هر کالا را در یک یا چند انبار می‌بینی. موجودی قابل فروش برابر موجودی واقعی منهای رزرو فعال است.','این بخش فقط با قابلیت قراردادی Inventory Pro فعال می‌شود.','Inventory Pro','Track each product across one or more locations. Available stock is on-hand minus active reservations.','This area is available only with the Inventory Pro entitlement.',true),
('inventory.balance','موجودی قابل فروش','On hand موجودی واقعی است؛ Reserved برای خریدهای در جریان کنار گذاشته شده و Available مقدار قابل فروش است.',null,'Available inventory','On hand is physical stock; Reserved is held for in-progress purchases; Available is sellable stock.',null,true),
('inventory.reservation','رزرو موجودی','در شروع خرید می‌توان کالا را برای مدت محدود رزرو کرد تا همزمان به دو نفر فروخته نشود. پرداخت موفق رزرو را قطعی و پرداخت ناموفق/منقضی آن را آزاد می‌کند.','رزرو و آزادسازی باید فقط توسط عملیات امن سرور انجام شود.','Inventory reservation','Stock can be held temporarily during checkout to prevent overselling. Successful payment commits it; failed or expired checkout releases it.','Reservation changes must only run through trusted server operations.',true),
('inventory.ledger','تاریخچه موجودی','هر ورود، فروش، مرجوعی، آسیب، اصلاح یا انتقال یک رکورد مستقل دارد؛ بنابراین علت تغییر موجودی قابل پیگیری است.',null,'Stock ledger','Every receipt, sale, return, damage, adjustment or transfer creates an immutable movement record for traceability.',null,true),
('inventory.transfer','انتقال بین انبارها','انتقال ابتدا ثبت و سپس دریافت می‌شود تا موجودی مبدا و مقصد قابل ردیابی بماند.','انتقال موجودی عملیات حساس است و باید ثبت رویداد و کنترل دسترسی داشته باشد.','Warehouse transfer','Transfers are created then received so stock remains traceable between source and destination.','Inventory transfers are sensitive and require authorization and audit logging.',true)
insert into public.guidance_articles(article_key,area,route_prefix,title_fa,summary_fa,body_fa,title_en,summary_en,body_en,keywords,importance,related_help_keys,active,sort_order) values('inventory.pro.guide','commerce','/admin/commerce/inventory','راهنمای انبارداری RAVA','از موجودی واقعی تا رزرو و انتقال','سه عدد را جدا ببین: موجودی واقعی، رزروشده و قابل فروش. تمام تغییرات باید در Stock Ledger ثبت شوند. هنگام Checkout موجودی می‌تواند موقتاً رزرو شود؛ در پرداخت موفق قطعی و در پرداخت ناموفق یا پایان زمان آزاد می‌شود. برای چند شعبه، موجودی هر Location جداست و انتقال بین آن‌ها تاریخچه مستقل دارد. هشدار Low Stock از نقطه سفارش مجدد هر کالا استفاده می‌کند.','RAVA Inventory Guide','From physical stock to reservations and transfers','Keep on-hand, reserved and available stock separate. Every movement belongs in the stock ledger. Checkout may temporarily reserve inventory; verified payment commits it, while failure or expiry releases it. Multi-location inventory is tracked independently with auditable transfers. Low-stock warnings use each item reorder point.',array['انبار','موجودی','رزرو','انتقال','inventory','stock','warehouse'],'important',array['inventory.overview','inventory.balance','inventory.reservation','inventory.ledger','inventory.transfer'],true,30) on conflict(article_key) do update set body_fa=excluded.body_fa,body_en=excluded.body_en,active=true;